+  cache: UrlCache,
+  minted: Map<string, string>,
+  nowMs: number,
+  ttlMs: number,
+): void {
+  for (const [path, entry] of cache) {
+    if (entry.expiresAtMs <= nowMs) cache.delete(path);
+  }
+  for (const [path, url] of minted) {
+    cache.set(path, { url, expiresAtMs: nowMs + ttlMs });
+  }
+}


